package io.github.diodeme.ji.remote;

import java.time.Duration;
import java.util.List;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicReference;

/**
 * Process boundary for exactly one cancellable operation. Cancelling destroys every live child process and
 * refuses to start new ones, so cancellation is bounded and cannot leave a resident SSH connection behind.
 */
final class CancellableProcessRunner implements ProcessRunner {
    private final ProcessRunner delegate;
    private final Set<RunningProcess> live = ConcurrentHashMap.newKeySet();
    private volatile boolean cancelled;

    CancellableProcessRunner(ProcessRunner delegate) {
        this.delegate = java.util.Objects.requireNonNull(delegate, "delegate");
    }

    boolean cancelled() { return cancelled; }

    /** Reclaims every live child process; the operation's worker observes cancellation through {@link #run}. */
    void cancel() {
        cancelled = true;
        for (RunningProcess process : List.copyOf(live)) close(process);
    }

    @Override
    public Result run(List<String> command, Duration timeout) {
        return run(command, timeout, process -> {});
    }

    @Override
    public Result run(List<String> command, Duration timeout, java.util.function.Consumer<RunningProcess> observer) {
        requireActive();
        var current = new AtomicReference<RunningProcess>();
        try {
            return delegate.run(command, timeout, process -> {
                current.set(process);
                live.add(process);
                observer.accept(process);
                if (cancelled) close(process);
            });
        } catch (RuntimeException failure) {
            throw activeFailure(failure);
        } finally {
            RunningProcess process = current.get();
            if (process != null) live.remove(process);
        }
    }
```

Hmm, careful: if `cancelled` and we `close(process)` inside the observer, the delegate's `waitFor` will return quickly and produce a non-zero exit → installer throws IllegalStateException → we map via `activeFailure` to OperationCancelledException. Good.

